package app.kivo.store;
import android.content.*;import android.net.Uri;import android.util.Base64;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
/** Itch OAuth authorization-code flow with per-attempt PKCE and state. */
final class ItchAuth {
 static final String CLIENT="3c6b4cd67b2adbe51079b0de2c705861", REDIRECT="app.kivo.store://itch/oauth";
 final MainActivity host;ItchAuth(MainActivity h){host=h;}
 String random(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return Base64.encodeToString(b,Base64.URL_SAFE|Base64.NO_PADDING|Base64.NO_WRAP);}
 void save(String key,String value)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,host.tokenKey());host.prefs.edit().putString(key,Base64.encodeToString(c.doFinal(value.getBytes("UTF-8")),Base64.NO_WRAP)).putString(key+"Iv",Base64.encodeToString(c.getIV(),Base64.NO_WRAP)).commit();}
 String read(String key){try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,host.tokenKey(),new GCMParameterSpec(128,Base64.decode(host.prefs.getString(key+"Iv",""),Base64.NO_WRAP)));return new String(c.doFinal(Base64.decode(host.prefs.getString(key,""),Base64.NO_WRAP)),"UTF-8");}catch(Exception e){return "";}}
 void clear(String key){host.prefs.edit().remove(key).remove(key+"Iv").apply();}
 void publish(){try{host.send("itchAuth",new JSONObject().put("connected",!read("itchToken").isEmpty()).put("login",host.prefs.getString("itchLogin","")));}catch(Exception ignored){}}
 void start(){try{String verifier=random(),state=random(),challenge=Base64.encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes("US-ASCII")),Base64.URL_SAFE|Base64.NO_PADDING|Base64.NO_WRAP);save("itchPending",new JSONObject().put("verifier",verifier).put("state",state).put("created",System.currentTimeMillis()).toString());Uri url=Uri.parse("https://itch.io/user/oauth").buildUpon().appendQueryParameter("client_id",CLIENT).appendQueryParameter("redirect_uri",REDIRECT).appendQueryParameter("response_type","code").appendQueryParameter("scope","profile:me game:view:uploads").appendQueryParameter("code_challenge",challenge).appendQueryParameter("code_challenge_method","S256").appendQueryParameter("state",state).build();host.runOnUiThread(()->{try{host.startActivity(new Intent(Intent.ACTION_VIEW,url));}catch(Exception e){host.status("No se pudo abrir el navegador.");}});}catch(Exception e){host.status("No se pudo iniciar la conexión con itch.io.");}}
 String request(String url,String method,String body,String token)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);if(token!=null)c.setRequestProperty("Authorization","Bearer "+token);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes("UTF-8"));}}try{int status=c.getResponseCode();if(status!=200)throw new IOException("itch.io respondió HTTP "+status);try(InputStream in=c.getInputStream()){return MainActivity.read(in,262144);}}finally{c.disconnect();}}
 static String form(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 void callback(Uri uri){if(uri==null||!"app.kivo.store".equals(uri.getScheme())||!"itch".equals(uri.getHost())||!"/oauth".equals(uri.getPath()))return;String pending=read("itchPending"),state=uri.getQueryParameter("state"),code=uri.getQueryParameter("code"),error=uri.getQueryParameter("error");try{JSONObject p=new JSONObject(pending);if(state==null||!MessageDigest.isEqual(state.getBytes("UTF-8"),p.getString("state").getBytes("UTF-8"))||System.currentTimeMillis()-p.getLong("created")>10*60*1000L)throw new IOException("La solicitud de conexión expiró o no coincide.");clear("itchPending");if(error!=null){host.status("Conexión con itch.io cancelada o rechazada.");return;}if(code==null||code.isEmpty())throw new IOException("Falta el código de autorización.");String verifier=p.getString("verifier");host.authJobs.execute(()->{try{String body="grant_type=authorization_code&code="+form(code)+"&code_verifier="+form(verifier)+"&redirect_uri="+form(REDIRECT)+"&client_id="+form(CLIENT);JSONObject tokenResponse=new JSONObject(request("https://api.itch.io/oauth/token","POST",body,null));String token=tokenResponse.getString("access_token");JSONObject profile=new JSONObject(request("https://api.itch.io/profile","GET",null,token)).getJSONObject("user");save("itchToken",token);host.prefs.edit().putString("itchLogin",profile.optString("username","")).apply();publish();host.status("Cuenta de itch.io conectada.");}catch(Exception e){host.status("No se pudo conectar itch.io: "+(e.getMessage()==null?"inténtalo de nuevo.":e.getMessage()));}});}catch(Exception e){clear("itchPending");host.status("No se pudo completar la conexión: "+e.getMessage());}}
 void logout(){String token=read("itchToken");clear("itchToken");clear("itchPending");host.prefs.edit().remove("itchLogin").apply();publish();host.status("Cuenta de itch.io desconectada de Kivo.");if(!token.isEmpty())host.authJobs.execute(()->{try{request("https://api.itch.io/oauth/revoke","POST","token="+form(token)+"&client_id="+form(CLIENT),null);}catch(Exception ignored){}});}
}
